/* Repair the review enrichment scope: each row must match its own product. */
SET NAMES utf8mb4;

UPDATE product_reviews r JOIN products p ON p.slug='litter-robot-4' SET
 summary='Whisker Litter-Robot 4 is a rotating self-cleaning litter box that sifts clumps after each visit and stores waste in a covered drawer. The supply bundle adds setup consumables, so confirm the exact Amazon bundle contents before checkout.',
 quick_specs_json=JSON_ARRAY(JSON_OBJECT('label','Litter type','value','Clumping litter'),JSON_OBJECT('label','Waste handling','value','Rotating globe + sealed drawer'),JSON_OBJECT('label','Noise','value','About 47 dB at 1 m'),JSON_OBJECT('label','Connectivity','value','Wi-Fi app'),JSON_OBJECT('label','Warranty','value','18 months'),JSON_OBJECT('label','Subscription','value','Optional features')),
 strengths_json=JSON_ARRAY('Rotating globe separates clean litter from waste','Large covered drawer reduces daily scooping','App records cycles and usage trends','Bundle includes filters, liners and odor supplies','No proprietary litter cartridge required'),
 limitations_json=JSON_ARRAY('High upfront bundle price','Requires compatible clumping litter','Entry may feel tight for very large cats','Odor consumables add recurring cost','Sensor alerts can pause a cycle until checked'),
 sections_json=JSON_ARRAY(JSON_OBJECT('title','Daily cleaning workflow','body','The globe rotates after a visit, sifts the clump and drops it into the drawer. Emptying the drawer and checking litter level remain regular tasks.'),JSON_OBJECT('title','Cat fit and transition','body','Measure the entrance, interior and service clearance. Keep a familiar box beside it while each cat learns the new routine.'),JSON_OBJECT('title','App and alerts','body','Cycle history and usage changes are useful context. Treat an alert as a prompt to inspect the unit, not proof of a specific fault.'),JSON_OBJECT('title','Maintenance and consumables','body','Clean sensor areas and accessible globe surfaces, and replace liners, filters or odor supplies as needed. Unplug before removing moving parts.'),JSON_OBJECT('title','Who should buy it','body','It suits multi-cat homes that can accommodate the footprint and value a mature rotating workflow. It is a weaker fit for very large cats or the lowest-cost households.'))
WHERE r.product_id=p.id AND r.is_published=TRUE;

UPDATE product_reviews r JOIN products p ON p.slug='petsafe-scoopfree-ultra' SET
 summary='PetSafe ScoopFree Crystal Pro Legacy is a crystal-tray self-cleaning litter box. It uses a simple rake-and-tray workflow that is easy to explain, but tray replacement determines ongoing cost.',
 quick_specs_json=JSON_ARRAY(JSON_OBJECT('label','Litter type','value','Crystal trays'),JSON_OBJECT('label','Waste handling','value','Automatic rake + disposable tray'),JSON_OBJECT('label','Connectivity','value','No app required'),JSON_OBJECT('label','Maintenance','value','Replace crystal tray'),JSON_OBJECT('label','Best fit','value','Single-cat homes')),
 strengths_json=JSON_ARRAY('Straightforward setup','Crystal tray contains urine and odor','No cloud account or subscription','Compact single-cat workflow'),
 limitations_json=JSON_ARRAY('Disposable tray cost','Crystal texture is not accepted by every cat','Rake path needs inspection','Less suitable for heavy multi-cat use'),
 sections_json=JSON_ARRAY(JSON_OBJECT('title','Tray workflow','body','The rake moves waste into the covered end after a delay. Replace the tray before saturation or odor becomes a problem.'),JSON_OBJECT('title','Cat acceptance','body','Introduce crystal gradually and keep a familiar box available. Do not mix incompatible litter types.'),JSON_OBJECT('title','Maintenance','body','Clear visible debris and unplug before inspecting the rake path or changing the tray.'),JSON_OBJECT('title','Space and noise','body','Measure the tray and service clearance, not only the housing, before choosing a location.'),JSON_OBJECT('title','Who should buy it','body','It is best for single-cat owners who prefer simple controls and accept disposable trays.'))
WHERE r.product_id=p.id AND r.is_published=TRUE;

UPDATE product_reviews r JOIN products p ON p.slug='jiobit-smart-tag' SET
 summary='Tractive Smart Cat GPS Tracker is a small connected tracker for cats that tolerate a collar attachment. Its value depends on coverage, safe attachment, battery routine and an active service plan.',
 quick_specs_json=JSON_ARRAY(JSON_OBJECT('label','Use','value','Outdoor cat location'),JSON_OBJECT('label','Connection','value','Cellular GPS'),JSON_OBJECT('label','App','value','Live location + safe zones'),JSON_OBJECT('label','Attachment','value','Cat-safe collar mount'),JSON_OBJECT('label','Plan','value','Required for remote tracking')),
 strengths_json=JSON_ARRAY('Small form factor','Live location and safe-zone alerts','Activity context helps interpret routines','Shared household access'),
 limitations_json=JSON_ARRAY('Requires coverage and subscription','Live mode drains battery faster','Not every cat accepts a tracker collar','Indoor location may be delayed'),
 sections_json=JSON_ARRAY(JSON_OBJECT('title','Location behavior','body','GPS estimates position and cellular service sends it to the app. Read timestamp and accuracy before acting on a location.'),JSON_OBJECT('title','Fit and safety','body','Use the documented attachment and confirm the collar can release safely. Watch for rubbing or behavior changes.'),JSON_OBJECT('title','Battery routine','body','Charge around the cat’s real roaming pattern; weak coverage and live mode use more power.'),JSON_OBJECT('title','Safe zones','body','Test the boundary at home. A safe-zone alert does not replace an ID tag or microchip.'),JSON_OBJECT('title','Who should buy it','body','It suits outdoor cats that tolerate the attachment and travel in supported coverage.'))
WHERE r.product_id=p.id AND r.is_published=TRUE;

UPDATE product_reviews r JOIN products p ON p.slug='petlibro-granary' SET
 summary='PETLIBRO Granary 5L Automatic Feeder is a scheduled dry-food dispenser with app control on supported models. Test repeatable portions with your food and keep a backup meal plan.',
 quick_specs_json=JSON_ARRAY(JSON_OBJECT('label','Food','value','Dry food'),JSON_OBJECT('label','Capacity','value','5 L hopper'),JSON_OBJECT('label','Control','value','Scheduled portions + app'),JSON_OBJECT('label','Power','value','Mains power; verify backup'),JSON_OBJECT('label','Cleaning','value','Removable food-contact parts')),
 strengths_json=JSON_ARRAY('Large hopper','Flexible portion programming','Remote schedule visibility','Easy-to-monitor chute and bowl'),
 limitations_json=JSON_ARRAY('Food shape affects portions','Wi-Fi problems can hide schedule status','Chute needs cleaning','Backup feeding remains essential'),
 sections_json=JSON_ARRAY(JSON_OBJECT('title','Portion accuracy','body','Weigh several portions using the food you actually buy and record variation.'),JSON_OBJECT('title','Food compatibility','body','Check kibble size and shape. Broken or oily pieces can bridge the chute.'),JSON_OBJECT('title','Offline behavior','body','Record schedules before resetting Wi-Fi and confirm whether local dispensing continues.'),JSON_OBJECT('title','Cleaning','body','Keep chute, bowl and sensor areas dry and clear; inspect after each food change.'),JSON_OBJECT('title','Who should buy it','body','It fits owners who want measured dry-food schedules and remote visibility.'))
WHERE r.product_id=p.id AND r.is_published=TRUE;

UPDATE product_reviews r JOIN products p ON p.slug='petsafe-healthy-pet-simply-feed' SET
