 quick_specs_json=JSON_ARRAY(JSON_OBJECT('label','Food','value','Dry food'),JSON_OBJECT('label','Control','value','On-device schedule'),JSON_OBJECT('label','Connectivity','value','No app required'),JSON_OBJECT('label','Portions','value','Timed servings'),JSON_OBJECT('label','Power','value','Verify battery or adapter setup')),
 strengths_json=JSON_ARRAY('Works without cloud account','Simple schedule is easy to audit','Good for routine dry-food meals','Fewer network settings'),
 limitations_json=JSON_ARRAY('No remote app status','Food shape affects portions','Cleaning is manual','Outage recovery needs checking'),
 sections_json=JSON_ARRAY(JSON_OBJECT('title','Schedule design','body','Program meals around the real routine and verify the next two servings after setup.'),JSON_OBJECT('title','Portion testing','body','Weigh multiple servings and adjust only after testing the actual food.'),JSON_OBJECT('title','Power recovery','body','Confirm the adapter or battery setup and recheck the clock after an outage.'),JSON_OBJECT('title','Cleaning','body','Empty crumbs from the chute and bowl; disconnect power before clearing a blockage.'),JSON_OBJECT('title','Who should buy it','body','It suits owners who value offline simplicity over remote controls.'))
