UPDATE product_reviews r JOIN products p ON p.slug='furbo-360' SET
 summary='Furbo 360 Dog Camera is a rotating indoor pet camera with two-way audio, night vision and treat interaction. Use it for quiet observation, not as a behavior treatment.',
 quick_specs_json=JSON_ARRAY(JSON_OBJECT('label','View','value','Rotating room coverage'),JSON_OBJECT('label','Audio','value','Two-way talk'),JSON_OBJECT('label','Interaction','value','Treat toss'),JSON_OBJECT('label','Night view','value','Low-light mode'),JSON_OBJECT('label','Plan','value','Some cloud features optional')),
 strengths_json=JSON_ARRAY('Wide rotating view','Clear live video and audio','Occasional treat interaction','Dog-focused notifications'),
 limitations_json=JSON_ARRAY('Cloud features may add cost','Remote voice can increase distress','Treat chute needs testing','Requires stable Wi-Fi'),
 sections_json=JSON_ARRAY(JSON_OBJECT('title','Observation workflow','body','Observe pacing, barking, settling and triggers before changing settings.'),JSON_OBJECT('title','Placement and privacy','body','Choose a stable view of the pet area, secure the cable and review account access.'),JSON_OBJECT('title','Audio and alerts','body','Test audio briefly because remote voices help some dogs and unsettle others.'),JSON_OBJECT('title','Treat interaction','body','Use compatible dry treats and test the landing area while supervised.'),JSON_OBJECT('title','Who should buy it','body','It fits owners who need broad visual coverage and occasional interaction.'))
WHERE r.product_id=p.id AND r.is_published=TRUE;

UPDATE product_reviews r JOIN products p ON p.slug='eufy-pet-camera-e220' SET
 summary='eufy Security Indoor Cam E220 is a general indoor camera for monitoring a pet without a pet-specific workflow. It is strongest when pan/tilt and local-style monitoring matter more than treats.',
 quick_specs_json=JSON_ARRAY(JSON_OBJECT('label','View','value','Indoor pan/tilt'),JSON_OBJECT('label','Storage','value','Verify local or cloud option'),JSON_OBJECT('label','Audio','value','Two-way talk'),JSON_OBJECT('label','Night view','value','Low light'),JSON_OBJECT('label','Best fit','value','General indoor monitoring')),
 strengths_json=JSON_ARRAY('Flexible pan and tilt','Useful general household camera','Can avoid pet-specific features','Simple live-view use case'),
 limitations_json=JSON_ARRAY('No treat workflow','Alerts vary by model and plan','Privacy settings need review','Placement determines blind spots'),
 sections_json=JSON_ARRAY(JSON_OBJECT('title','Monitoring workflow','body','Define the room and behavior to observe. A general camera is enough when live video and basic alerts are the only requirements.'),JSON_OBJECT('title','Storage and privacy','body','Decide where clips live, who can access them and how long they remain.'),JSON_OBJECT('title','Placement','body','Use a stable surface with a clear view and test night visibility and audio delay.'),JSON_OBJECT('title','Connectivity','body','Test near the final location and verify recovery after a router restart.'),JSON_OBJECT('title','Who should buy it','body','It suits owners who want general indoor monitoring and pan/tilt.'))
